CREATE TABLE care_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinic_id uuid NOT NULL REFERENCES clinics(id),service_id uuid NOT NULL,name text NOT NULL,price_minor bigint NOT NULL CHECK(price_minor>0),uses integer NOT NULL CHECK(uses BETWEEN 1 AND 100),valid_days integer NOT NULL CHECK(valid_days BETWEEN 1 AND 730),active boolean NOT NULL DEFAULT true,FOREIGN KEY(service_id,clinic_id) REFERENCES clinic_services(id,clinic_id));
CREATE TABLE care_subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),plan_id uuid NOT NULL REFERENCES care_plans(id),pet_id uuid NOT NULL REFERENCES pets(id),user_id uuid NOT NULL REFERENCES users(id),uses_total integer NOT NULL,uses_used integer NOT NULL DEFAULT 0,price_minor bigint NOT NULL,expires_at timestamptz NOT NULL,idempotency_key uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(uses_used BETWEEN 0 AND uses_total),UNIQUE(user_id,idempotency_key));
CREATE TABLE entitlement_usage(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subscription_id uuid NOT NULL REFERENCES care_subscriptions(id),encounter_id uuid NOT NULL UNIQUE REFERENCES encounters(id),actor_id uuid NOT NULL REFERENCES users(id),used_at timestamptz NOT NULL DEFAULT now(),UNIQUE(subscription_id,encounter_id));
CREATE TRIGGER usage_immutable BEFORE UPDATE OR DELETE ON entitlement_usage FOR EACH ROW EXECUTE FUNCTION protect_addendum();
CREATE TABLE boarding_units(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinic_id uuid NOT NULL REFERENCES clinics(id),name text NOT NULL,species text NOT NULL,night_price bigint NOT NULL CHECK(night_price>0),active boolean NOT NULL DEFAULT true,UNIQUE(clinic_id,name));
CREATE TABLE boarding_bookings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),unit_id uuid NOT NULL REFERENCES boarding_units(id),pet_id uuid NOT NULL REFERENCES pets(id),user_id uuid NOT NULL REFERENCES users(id),starts_on date NOT NULL,ends_on date NOT NULL,total_minor bigint NOT NULL CHECK(total_minor>0),status text NOT NULL DEFAULT 'confirmed' CHECK(status IN ('confirmed','checked_in','completed','cancelled')),idempotency_key uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_on>starts_on),UNIQUE(user_id,idempotency_key),EXCLUDE USING gist(unit_id WITH =,daterange(starts_on,ends_on,'[)') WITH &&) WHERE(status IN ('confirmed','checked_in')));
CREATE TABLE care_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),appointment_id uuid NOT NULL REFERENCES appointments(id),actor_id uuid NOT NULL REFERENCES users(id),body text NOT NULL,idempotency_key uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(actor_id,idempotency_key));
CREATE TABLE pet_transfers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),pet_id uuid NOT NULL REFERENCES pets(id),from_id uuid NOT NULL REFERENCES users(id),to_id uuid NOT NULL REFERENCES users(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','cancelled')),expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days',created_at timestamptz NOT NULL DEFAULT now(),CHECK(from_id<>to_id));
CREATE UNIQUE INDEX one_pending_transfer ON pet_transfers(pet_id) WHERE status='pending';
CREATE TABLE pet_ownership_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),pet_id uuid NOT NULL REFERENCES pets(id),from_id uuid NOT NULL REFERENCES users(id),to_id uuid NOT NULL REFERENCES users(id),transfer_id uuid NOT NULL UNIQUE REFERENCES pet_transfers(id),occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER ownership_immutable BEFORE UPDATE OR DELETE ON pet_ownership_history FOR EACH ROW EXECUTE FUNCTION protect_addendum();
CREATE TABLE pet_weights(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),pet_id uuid NOT NULL REFERENCES pets(id),actor_id uuid NOT NULL REFERENCES users(id),grams integer NOT NULL CHECK(grams>0),measured_on date NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
